native.command_script:
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
function Fingerprint([string]$Path,[string]$Expected,[long]$Bytes=-1){
 $item=Get-Item -LiteralPath $Path
 $actual=(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()
 if($actual -ne $Expected -or ($Bytes -ge 0 -and $item.Length -ne $Bytes)){throw ('Changed input: '+$Path)}
 return [ordered]@{path=$Path;sha256=$actual;bytes=$item.Length}
}
$sourcePath='P:/projects/packed-gate-midpoint-package-source-r2.json'
$sourceFile=Fingerprint $sourcePath 'b6bb3aad0f65814a8549a905f9548a844208f11a07f1962c2415818962f527f6'
$m=[IO.File]::ReadAllText($sourcePath)|ConvertFrom-Json
$inputPath=Join-Path 'P:/projects' $m.input
$inputFile=Fingerprint $inputPath $m.input_sha256
$c=[IO.File]::ReadAllText($inputPath)|ConvertFrom-Json
$scriptPath=Join-Path 'P:/projects' $m.script
$scriptFile=Fingerprint $scriptPath $m.script_sha256
$tokens=$null;$errors=$null;$null=[Management.Automation.Language.Parser]::ParseFile($scriptPath,[ref]$tokens,[ref]$errors)
if($errors.Count){throw ($errors|Out-String)}
$components=@()
foreach($entry in $c.components.PSObject.Properties){
 $x=$entry.Value
 $expectedBytes=-1
 if($x.artifact.PSObject.Properties.Name -contains 'bytes'){$expectedBytes=[long]$x.artifact.bytes}
 $artifact=Fingerprint $x.artifact.path $x.artifact.sha256 $expectedBytes
 $metaFile=Fingerprint $x.metadata.path $x.metadata.sha256
 $meta=[IO.File]::ReadAllText($x.metadata.path)|ConvertFrom-Json
 if($meta.repo_commit -ne $x.commit -or $meta.dirty_tree){throw 'Component source mismatch'}
 $runFile=Fingerprint $x.build_run.path $x.build_run.sha256
 $run=[IO.File]::ReadAllText($x.build_run.path)|ConvertFrom-Json
 if($run.spec.repo_commit -ne $x.commit -or $run.reason -ne 'completed' -or $run.exit_code -ne 0 -or -not $run.host_checks_pass){throw 'Component build not qualified'}
 $components+=[ordered]@{role=$entry.Name;commit=$x.commit;artifact=$artifact;metadata=$metaFile;build_run=$runFile}
}
$extra=@();foreach($x in $c.extra_artifacts){$extra+=Fingerprint $x.path $x.sha256 ([long]$x.bytes)}
$base=Fingerprint $c.base_manifest.path $c.base_manifest.sha256
$controls=@();foreach($entry in $c.functional_prerequisites.PSObject.Properties){$controls+=Fingerprint $entry.Value.remote_run_record $entry.Value.run_record_sha256}
$equivalence=@();foreach($x in $c.server_source_equivalence.compared_inputs){
 $repaired=Fingerprint (Join-Path $c.repo $x.file) $x.repaired_tree_sha256 ([long]$x.bytes)
 $server=Fingerprint (Join-Path $c.server_working_directory $x.file) $x.server_build_sha256 ([long]$x.bytes)
 if($repaired.sha256 -ne $server.sha256){throw 'Server input differs'}
 $equivalence+=[ordered]@{file=$x.file;repaired=$repaired;server=$server}
}
$active=@();foreach($owner in @($m.exclusive_host_predecessor)+@($m.additional_host_predecessors)){
 $active+=[ordered]@{run_directory=$owner.run_directory;record_present=(Test-Path -LiteralPath $owner.remote_run_record)}
}
[ordered]@{host=[Environment]::MachineName;utc=[DateTime]::UtcNow.ToString('o');source=$sourceFile;input=$inputFile;script=$scriptFile;parse_errors=@();components=$components;extra_artifacts=$extra;base_manifest=$base;functional_controls=$controls;active_owners=$active;server_input_equivalence=$equivalence;artifact_binding_verified=$true;archive_created=$false;new_model_process_launched=$false;gpu_test_launched=$false}|ConvertTo-Json -Depth 12
